create extension if not exists pgcrypto;
create type public.wallet_type as enum('bid','income');
create type public.member_id_type as enum('main','duplicate');
create type public.payment_status as enum('pending','approved','rejected');
create type public.auction_status as enum('draft','scheduled','active','ended','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,role text not null default 'member' check(role in('member','admin','support','finance')),status text not null default 'active',created_at timestamptz not null default now());
create table public.member_ids(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,member_code text not null unique,id_type public.member_id_type not null default 'main',main_member_id uuid references public.member_ids(id),parent_member_id uuid references public.member_ids(id),created_at timestamptz not null default now());
create unique index one_main_member_per_user on public.member_ids(user_id) where id_type='main';
create table public.packages(id uuid primary key default gen_random_uuid(),name text not null,description text,price numeric(14,2) not null default 0 check(price>=0),currency text not null default 'INR',bid_wallet_credit numeric(14,2) not null default 0 check(bid_wallet_credit>=0),benefits jsonb not null default '{}'::jsonb,is_active boolean not null default false,created_at timestamptz not null default now());
create table public.package_activations(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),member_id uuid not null references public.member_ids(id),package_id uuid not null references public.packages(id),activation_no int not null check(activation_no>0),amount numeric(14,2) not null check(amount>=0),payment_reference text not null unique,receipt_path text,status public.payment_status not null default 'pending',verified_by uuid references public.profiles(id),verified_at timestamptz,created_at timestamptz not null default now(),unique(member_id,activation_no));
create table public.wallet_accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,wallet_type public.wallet_type not null,balance numeric(14,2) not null default 0 check(balance>=0),currency text not null default 'INR',updated_at timestamptz not null default now(),unique(user_id,wallet_type));
create table public.wallet_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),wallet_account_id uuid not null references public.wallet_accounts(id),transaction_type text not null,amount numeric(14,2) not null check(amount>0),balance_after numeric(14,2) not null check(balance_after>=0),reference_type text,reference_id uuid,idempotency_key text not null unique,description text,created_at timestamptz not null default now());
create table public.referral_plan_versions(id uuid primary key default gen_random_uuid(),package_id uuid not null references public.packages(id),version_no int not null,status text not null default 'draft',created_at timestamptz not null default now(),unique(package_id,version_no));
create table public.referral_level_rules(id uuid primary key default gen_random_uuid(),plan_version_id uuid not null references public.referral_plan_versions(id),level_no int not null check(level_no>0),reward_kind text not null check(reward_kind in('fixed','percent')),reward_value numeric(14,4) not null check(reward_value>=0),eligibility jsonb not null default '{}'::jsonb,unique(plan_version_id,level_no));
create table public.referrals(id uuid primary key default gen_random_uuid(),referred_user_id uuid not null references public.profiles(id),referred_member_id uuid not null references public.member_ids(id),referrer_member_id uuid references public.member_ids(id),main_member_id uuid references public.member_ids(id),created_at timestamptz not null default now(),unique(referred_member_id));
create table public.referral_commissions(id uuid primary key default gen_random_uuid(),source_activation_id uuid not null references public.package_activations(id),recipient_user_id uuid not null references public.profiles(id),reporting_member_id uuid not null references public.member_ids(id),credited_wallet_id uuid not null references public.wallet_accounts(id),level_no int not null,amount numeric(14,2) not null check(amount>=0),plan_version_id uuid not null references public.referral_plan_versions(id),status text not null default 'pending',created_at timestamptz not null default now(),unique(source_activation_id,reporting_member_id,level_no));
create table public.products(id uuid primary key default gen_random_uuid(),title text not null,description text,image_url text,category text,is_active boolean not null default false,created_at timestamptz not null default now());
create table public.auctions(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id),title text not null,description text,image_url text,category text,starting_price numeric(14,2) not null check(starting_price>=0),current_price numeric(14,2) not null check(current_price>=0),minimum_increment numeric(14,2) not null check(minimum_increment>0),currency text not null default 'INR',starts_at timestamptz not null,ends_at timestamptz not null,status public.auction_status not null default 'draft',winner_user_id uuid references public.profiles(id),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.fixed_bid_campaigns(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id),title text not null,description text,entry_amount numeric(14,2) not null check(entry_amount>0),currency text not null default 'INR',starts_at timestamptz not null,ends_at timestamptz not null,status public.auction_status not null default 'draft',rules jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.bids(id uuid primary key default gen_random_uuid(),auction_id uuid not null references public.auctions(id),user_id uuid not null references public.profiles(id),amount numeric(14,2) not null check(amount>0),created_at timestamptz not null default now());
create index bids_auction_time_idx on public.bids(auction_id,created_at desc);
create table public.fixed_bids(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.fixed_bid_campaigns(id),user_id uuid not null references public.profiles(id),amount numeric(14,2) not null check(amount>0),created_at timestamptz not null default now(),unique(campaign_id,user_id));
create table public.withdrawal_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),amount numeric(14,2) not null check(amount>0),currency text not null default 'INR',status public.payment_status not null default 'pending',reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,rejection_reason text,created_at timestamptz not null default now());
create table public.winning_item_payments(id uuid primary key default gen_random_uuid(),auction_id uuid not null references public.auctions(id),user_id uuid not null references public.profiles(id),amount numeric(14,2) not null check(amount>0),status public.payment_status not null default 'pending',payment_reference text unique,paid_at timestamptz,created_at timestamptz not null default now());
create table public.delivery_tracking(id uuid primary key default gen_random_uuid(),winning_payment_id uuid not null references public.winning_item_payments(id),carrier text,tracking_number text,status text not null default 'pending',notes text,updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.app_settings(setting_key text primary key,setting_value jsonb not null,updated_at timestamptz not null default now());
insert into public.app_settings values('bidding_enabled','false'),('fixed_bid_enabled','false'),('withdrawals_enabled','false'),('duplicate_ids_enabled','false'),('winner_selection_configured','false') on conflict do nothing;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin
insert into public.profiles(id,email,display_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict do nothing;
insert into public.wallet_accounts(user_id,wallet_type,balance) values(new.id,'bid',0),(new.id,'income',0) on conflict(user_id,wallet_type) do nothing;return new;end $$;
revoke all on function public.handle_new_user() from public,anon,authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
do $$ declare t text; begin foreach t in array array['profiles','member_ids','packages','package_activations','wallet_accounts','wallet_transactions','referral_plan_versions','referral_level_rules','referrals','referral_commissions','products','auctions','fixed_bid_campaigns','bids','fixed_bids','withdrawal_requests','winning_item_payments','delivery_tracking','audit_logs','app_settings'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create policy profiles_own on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy member_ids_own on public.member_ids for select to authenticated using(user_id=(select auth.uid()));
create policy packages_active on public.packages for select to authenticated using(is_active);
create policy activations_own on public.package_activations for select to authenticated using(user_id=(select auth.uid()));
create policy wallets_own on public.wallet_accounts for select to authenticated using(user_id=(select auth.uid()));
create policy wallet_tx_own on public.wallet_transactions for select to authenticated using(user_id=(select auth.uid()));
create policy products_active on public.products for select to authenticated using(is_active);
create policy auctions_visible on public.auctions for select to authenticated using(status in('scheduled','active','ended'));
create policy fixed_campaigns_visible on public.fixed_bid_campaigns for select to authenticated using(status in('scheduled','active','ended'));
create policy bids_own on public.bids for select to authenticated using(user_id=(select auth.uid()));
create policy fixed_bids_own on public.fixed_bids for select to authenticated using(user_id=(select auth.uid()));
create policy withdrawals_own on public.withdrawal_requests for select to authenticated using(user_id=(select auth.uid()));
create policy winning_payments_own on public.winning_item_payments for select to authenticated using(user_id=(select auth.uid()));
create policy delivery_own on public.delivery_tracking for select to authenticated using(exists(select 1 from public.winning_item_payments p where p.id=winning_payment_id and p.user_id=(select auth.uid())));
create policy referrals_own on public.referrals for select to authenticated using(referred_user_id=(select auth.uid()));
create policy commissions_own on public.referral_commissions for select to authenticated using(recipient_user_id=(select auth.uid()));
revoke insert,update,delete,truncate,references,trigger on all tables in schema public from anon,authenticated;
grant select on public.profiles,public.member_ids,public.packages,public.package_activations,public.wallet_accounts,public.wallet_transactions,public.products,public.auctions,public.fixed_bid_campaigns,public.bids,public.fixed_bids,public.withdrawal_requests,public.winning_item_payments,public.delivery_tracking,public.referrals,public.referral_commissions to authenticated;
